const op = ($.input.operation || '').toLowerCase();
if (op !== 'list-event-types' && op !== 'get-slots') throw new Error('operation must be "list-event-types" or "get-slots"');
if (op === 'get-slots' && (!$.input.eventTypeId || !$.input.startTime || !$.input.endTime)) throw new Error('get-slots requires eventTypeId, startTime, and endTime');
return { op };

const op = $.steps.route.output.op;
if (op === 'list-event-types') {
  const resp = $.steps.listEventTypes?.response || {};
  const types = resp.data?.eventTypes || resp.event_types || resp.data || [];
  const list = Array.isArray(types) ? types : [];
  return {
    eventTypes: list.map(t => ({ id: t.id, title: t.title, slug: t.slug, length: t.length, description: t.description })),
    count: list.length,
    summary: `Found ${list.length} event type${list.length === 1 ? '' : 's'}`
  };
} else {
  const resp = $.steps.getSlots?.response || {};
  const slots = resp.data?.slots || resp.slots || resp.data || {};
  const allSlots = Object.values(slots).flat();
  return {
    slots,
    totalSlots: allSlots.length,
    summary: `Found ${allSlots.length} available slot${allSlots.length === 1 ? '' : 's'}`
  };
}
